def single_number_iii(nums):
    xor_sum = 0
    for num in nums:
        xor_sum ^= num
    # Rightmost set bit
    diff_bit = xor_sum & (-xor_sum)
    num1 = num2 = 0
    for num in nums:
        if num & diff_bit:
            num1 ^= num
        else:
            num2 ^= num
    return [num1, num2]

