def subsets(nums):
    n = len(nums)
    total = 1 << n
    res = []
    for mask in range(total):
        sub = []
        for i in range(n):
            if mask & (1 << i):
                sub.append(nums[i])
        res.append(sub)
    return res

def get_sum(a, b):
    MASK = 0xFFFFFFFF
    MAX_INT = 0x7FFFFFFF
    while b != 0:
        carry = (a & b) << 1
        a = (a ^ b) & MASK
        b = carry & MASK
    return a if a <= MAX_INT else ~(a ^ MASK)

def enumerate_submasks(mask):
    submask = mask
    submasks = []
    while True:
        submasks.append(submask)
        if submask == 0:
            break
        submask = (submask - 1) & mask
    return submasks

def reverse_bits(n):
    res = 0
    for _ in range(32):
        res = (res << 1) | (n & 1)
        n >>= 1
    return res

